import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testFilterGreaterThan() {
        Assert.assertEquals(listOf(4, 5), myFilter(listOf(1, 2, 3, 4, 5), { it > 3 }))
    }

    @Test
    fun testFilterMinimum() {
        Assert.assertEquals(listOf(20, 25), myFilter(listOf(10, 15, 20, 25), { it >= 20 }))
    }

    @Test
    fun testFilterEven() {
        Assert.assertEquals(listOf(2, 4, 6), myFilter(listOf(1, 2, 3, 4, 5, 6), { it % 2 == 0 }))
    }

    @Test
    fun testFilterNoneMatch() {
        Assert.assertEquals(emptyList<Int>(), myFilter(listOf(1, 2, 3), { it > 10 }))
    }

    @Test
    fun testFilterEmptyList() {
        Assert.assertEquals(emptyList<Int>(), myFilter(emptyList(), { it > 0 }))
    }
}
